import static org.mockito.Mockito.when;

public class ContextualRenamer_addDeclaredName_TriageGen2Test {

    private MakeDeclaredNamesUnique.ContextualRenamer renamer;
    private Map<String, String> declarations;

    @Before
    public void setUp() throws Exception {
        renamer = spy(new MakeDeclaredNamesUnique.ContextualRenamer());
        declarations = new HashMap<>();

        // Injecting the private 'declarations' field via reflection to control state
        Field declarationsField = MakeDeclaredNamesUnique.ContextualRenamer.class.getDeclaredField("declarations");
        declarationsField.setAccessible(true);
        declarationsField.set(renamer, declarations);
    }

    /**
     * Test branch: global == true
     */
    @Test
    public void testAddDeclaredName_GlobalTrue() {
        setGlobal(true);
        String name = "myVar";

        renamer.addDeclaredName(name);

        verify(renamer).reserveName(name);
    }

    /**
     * Test branch: global == false AND name is already in declarations
     */
    @Test
    public void testAddDeclaredName_LocalNotGlobal_AlreadyExists() {
        setGlobal(false);
        String name = "myVar";
        declarations.put(name, "renamedVar");

        renamer.addDeclaredName(name);

        // Should not call incrementNameCount or put
        verify(renamer, org.mockito.Mockito.never()).incrementNameCount(name);
        assertEquals("renamedVar", declarations.get(name));
    }

    /**
     * Test branch: global == false AND name is NOT in declarations AND id != 0
     */
    @Test
    public void testAddDeclaredName_LocalNotGlobal_NewNameWithId() {
        setGlobal(false);
        String name = "myVar";
        int id = 1;
        String expectedNewName = "myVar_1";

        when(renamer.incrementNameCount(name)).thenReturn(id);
        when(renamer.getUniqueName(name, id)).thenReturn(expectedNewName);

        renamer.addDeclaredName(name);

        assertEquals(expectedNewName, declarations.get(name));
        verify(renamer).incrementNameCount(name);
        verify(renamer).getUniqueName(name, id);
    }

    /**
     * Test branch: global == false AND name is NOT in declarations AND id == 0
     */
    @Test
    public void testAddDeclaredName_LocalNotGlobal_NoId() {
        setGlobal(false);
        String name = "myVar";
        int id = 0;

        when(renamer.incrementNameCount(name)).thenReturn(id);

        renamer.addDeclaredName(name);

        // newName remains null if id == 0
        assertEquals(null, declarations.get(name));
        verify(renamer).incrementNameCount(name);
        verify(renamer, org.mockito.Mockito.never()).getUniqueName(org.mockito.ArgumentMatchers.anyString(), org.mockito.ArgumentMatchers.anyInt());
    }

    private void setGlobal(boolean global) throws Exception {
        Field globalField = MakeDeclaredNamesUnique.ContextualRenamer.class.getDeclaredField("global");
        globalField.setAccessible(true);
        globalField.set(renamer, global);
    }
}
